const state = $getWorkflowStaticData('global');
const lastSeenId = typeof state.lastKpiMessageId === 'string' ? state.lastKpiMessageId : null;
const items = $input.all();
const valid = items.flatMap((item) => {
  const message = item.json || {};
  const id = String(message.id ?? message.messageId ?? '');
  if (!/^\d{17,20}$/.test(id)) return [];
  return [{ message, id }];
});
valid.sort((left, right) => BigInt(left.id) < BigInt(right.id) ? -1 : 1);
const newestId = valid.at(-1)?.id ?? null;
if (lastSeenId === null) {
  if (newestId) state.lastKpiMessageId = newestId;
  console.log('[kpi-bot] watermark inicializado', { newestId });
  return [];
}
const newer = valid.filter(({ id }) => BigInt(id) > BigInt(lastSeenId));
if (newer.length === 0) return [];
const watermarkCandidate = newer.at(-1).id;
const normalize = (value) => String(value || '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim()
  .toLowerCase();
const commands = [];
for (const { message, id } of newer) {
  if (message.author && message.author.bot === true) continue;
  const original = typeof message.content === 'string' ? message.content.trim() : '';
  const content = normalize(original);
  let command = null;
  let query = '';
  if (['zack revisa', 'zack revisa de nuevo', 'revisa de nuevo'].includes(content)) {
    command = 'review';
  } else if (['zack ayuda', 'ayuda zack'].includes(content)) {
    command = 'help';
  } else if (content.startsWith('zack detalle ')) {
    command = 'detail';
    query = original.slice(original.toLowerCase().indexOf('detalle') + 7).trim();
  } else if (content.startsWith('dame mas informacion')) {
    command = 'detail';
    query = original.replace(/^dame\s+m[aá]s\s+informaci[oó]n(?:\s+(?:de|sobre))?\s*/i, '').trim();
  }
  if (command) commands.push({ json: { command, query, sourceMessageId: id, watermarkCandidate } });
}
if (commands.length === 0) {
  state.lastKpiMessageId = watermarkCandidate;
  console.log('[kpi-bot] sin comandos nuevos', { watermarkCandidate });
  return [];
}
return commands;

const requests = $('Detectar comandos nuevos').all();
const responses = $input.all();
const output = [];
for (let index = 0; index < responses.length; index += 1) {
  const request = requests[index]?.json || {};
  const response = responses[index]?.json || {};
  let messages;
  if (request.command === 'help') {
    messages = ['## 🤖 ZACK · KPI REPORTING\n`zack revisa` — vuelve a calcular el informe\n`zack detalle <creador, marca o trato>` — muestra información concreta\n`zack ayuda` — recuerda estos comandos'];
  } else if (request.command === 'detail' && !String(request.query || '').trim()) {
    messages = ['ℹ️ Indica qué trato buscas. Ejemplo: `zack detalle Curly Keydrop`.'];
  } else {
    messages = Array.isArray(response.discordMessages) ? response.discordMessages : [];
  }
  for (const content of messages) {
    if (typeof content !== 'string' || !content.trim()) continue;
    output.push({ json: { content, sourceMessageId: request.sourceMessageId, watermarkCandidate: request.watermarkCandidate } });
  }
}
return output;

const replies = $('Preparar respuestas').all();
const candidates = replies
  .map((item) => String(item.json.watermarkCandidate || ''))
  .filter((id) => /^\d{17,20}$/.test(id));
if (candidates.length === 0) return [];
const maxId = candidates.reduce((max, id) => BigInt(id) > BigInt(max) ? id : max, candidates[0]);
const state = $getWorkflowStaticData('global');
state.lastKpiMessageId = maxId;
console.log('[kpi-bot] comandos respondidos', { maxId, replies: replies.length });
return [];
